unsafe fn scan_tree(
    mut s: *mut deflate_state,
    mut tree: *mut ct_data,
    mut max_code: c_int,
) {
    let mut prevlen: c_int = -(1 as c_int);
    let mut curlen: c_int;
    // SAFETY: `tree[max_code + 1]` is written below and `tree[n + 1]` is read for
    // every `n` in `0..=max_code`, so the caller contract for this function already
    // requires `tree` to be non-null and valid for `max_code + 2` contiguous
    // `ct_data` elements. No other reference to this region is created here.
    let tree = unsafe { core::slice::from_raw_parts_mut(tree, (max_code + 2) as usize) };
    let mut nextlen: c_int = tree[0].dl.len as c_int;
    let mut count: c_int = 0 as c_int;
    let mut max_count: c_int = 7 as c_int;
    let mut min_count: c_int = 4 as c_int;
    if nextlen == 0 as c_int {
        max_count = 138 as c_int;
        min_count = 3 as c_int;
    }
    tree[(max_code + 1 as c_int) as usize].dl.len = 0xffff as c_int as ush;

    let bl_tree = &mut (*s).bl_tree;
    for n in 0..=(max_code as usize) {
        curlen = nextlen;
        nextlen = tree[n + 1].dl.len as c_int;
        count += 1;
        if !(count < max_count && curlen == nextlen) {
            if count < min_count {
                // SAFETY: `curlen` is a bit-length code used as an index into `bl_tree`;
                // in this routine it is always within the valid `bl_tree` domain.
                unsafe {
                    (*bl_tree.get_unchecked_mut(curlen as usize)).fc.freq =
                        ((*bl_tree.get_unchecked(curlen as usize)).fc.freq as c_int + count) as ush;
                }
            } else if curlen != 0 as c_int {
                if curlen != prevlen {
                    // SAFETY: `curlen` is within the valid `bl_tree` domain for the same
                    // reason as above.
                    unsafe {
                        (*bl_tree.get_unchecked_mut(curlen as usize)).fc.freq =
                            (*bl_tree.get_unchecked(curlen as usize)).fc.freq.wrapping_add(1);
                    }
                }
                // SAFETY: `REP_3_6` is a fixed valid index into `bl_tree`.
                unsafe {
                    (*bl_tree.get_unchecked_mut(REP_3_6 as usize)).fc.freq =
                        (*bl_tree.get_unchecked(REP_3_6 as usize)).fc.freq.wrapping_add(1);
                }
            } else if count <= 10 as c_int {
                // SAFETY: `REPZ_3_10` is a fixed valid index into `bl_tree`.
                unsafe {
                    (*bl_tree.get_unchecked_mut(REPZ_3_10 as usize)).fc.freq =
                        (*bl_tree.get_unchecked(REPZ_3_10 as usize)).fc.freq.wrapping_add(1);
                }
            } else {
                // SAFETY: `REPZ_11_138` is a fixed valid index into `bl_tree`.
                unsafe {
                    (*bl_tree.get_unchecked_mut(REPZ_11_138 as usize)).fc.freq =
                        (*bl_tree.get_unchecked(REPZ_11_138 as usize)).fc.freq.wrapping_add(1);
                }
            }
            count = 0 as c_int;
            prevlen = curlen;
            if nextlen == 0 as c_int {
                max_count = 138 as c_int;
                min_count = 3 as c_int;
            } else if curlen == nextlen {
                max_count = 6 as c_int;
                min_count = 3 as c_int;
            } else {
                max_count = 7 as c_int;
                min_count = 4 as c_int;
            }
        }
    }
